        x = parent[x];
    }
    return x;
}

void unite(std::vector<int>& parent, int a, int b) {
    int ra = findRoot(parent, a);
    int rb = findRoot(parent, b);
    if (ra != rb) {
        parent[rb] = ra;
    }
}

int main() {
    int n = 0;
    int m = 0;
    std::cin >> n >> m;
    std::vector<int> parent(n);
    std::iota(parent.begin(), parent.end(), 0);
    for (int i = 0; i < m; ++i) {
        int a = 0;
        int b = 0;
        std::cin >> a >> b;
        unite(parent, a, b);
    }
    int q = 0;
    std::cin >> q;
    for (int i = 0; i < q; ++i) {
        int a = 0;
        int b = 0;
        std::cin >> a >> b;
        bool same = findRoot(parent, a) == findRoot(parent, b);
        std::cout << a << " and " << b << ": " << (same ? "same group" : "different groups") << '\n';
    }
    return 0;
}

